SELECT wr_reason_sk, i_category, total_loss, return_cnt, loss_category, RANK() OVER (PARTITION BY loss_category ORDER BY total_loss DESC) AS category_rank, SUM(total_loss) OVER (PARTITION BY i_category) AS category_total FROM ( SELECT wr.wr_reason_sk, i.i_category, SUM(wr.wr_net_loss) AS total_loss, COUNT(*) AS return_cnt, CASE WHEN SUM(wr.wr_net_loss) > 25000 THEN 'HIGH' WHEN SUM(wr.wr_net_loss) > 12000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN customer_address ca ON wr.wr_returning_addr_sk = ca.ca_address_sk WHERE i.i_brand = 'BrandX' GROUP BY wr.wr_reason_sk, i.i_category ) agg ORDER BY i_category, category_rank
